const {chromium}=require('playwright'),assert=require('assert'),path=require('path'),fs=require('fs');
(async()=>{const browser=await chromium.launch({headless:true,executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'});try{const page=await browser.newPage({viewport:{width:1200,height:900}});await page.goto(process.argv[2]);await page.waitForFunction(()=>!document.querySelector('#ebookTask').hidden);assert(await page.locator('#ebookRetry').isVisible(),'failed job must offer retry');assert(await page.locator('#ebookCancel').isHidden());const status=await page.locator('#ebookStatus').textContent();assert(/failed|timeout|失败|超时|timed out/i.test(status));const out=path.resolve('demo-output/ebook-ui');fs.mkdirSync(out,{recursive:true});await page.screenshot({path:path.join(out,'real-failure.png'),fullPage:true});console.log(JSON.stringify({status,retryVisible:true,screenshot:path.join(out,'real-failure.png')}));}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
